# Composition root. Get-EmbeddedAsset is generated by build.ps1.

function Start-SynologyFilterTool {
    $ErrorActionPreference = 'Stop'
    $ports = New-SynologyPorts -SynologyHome (Get-SynologyHome) -TemplateText (Get-EmbeddedAsset -Name 'template')
    Start-ToolServer -Ports $ports -Html (Get-EmbeddedAsset -Name 'web')
}
